/** Trusted, root-reviewed JSON configuration only. Parsing does not issue runtime admission. */
export function parseDuoGenerationRegistry(value: unknown, primary: Deployment): DuoGenerationRegistry {
  const registry = record(value, "registry");
  exact(registry, ["schema", "version", "primaryFactory", "generations"], "registry");
  require_(registry.schema === DUO_GENERATION_REGISTRY_SCHEMA && registry.version === 1, "unsupported registry schema or version.");
  const primaryFactory = addr(registry.primaryFactory, "primary Factory");
  require_(same(primaryFactory, primary.factory), "primary Factory cannot be retargeted.");
  require_(Array.isArray(registry.generations) && registry.generations.length === 1,
    "exactly one complete V2 successor bundle is required when the registry is present.");
  const generations = registry.generations.map((raw: unknown) => {
    const entry = record(raw, "entry");
    exact(entry, ["policyVersion", "deployment", "source"], "entry");
    require_(entry.policyVersion === 2, "unknown policy generation.");
    const wire = record(entry.deployment, "Deployment bundle");
    require_(Object.keys(wire).every(key => bundleKeys.includes(key)),
      "Deployment bundle cannot contain nested registries or Pro/NFT overrides.");
    const deployment = parseDeployment(wire);
    require_(deployment.chainId === primary.chainId && deployment.environment === primary.environment &&
      new URL(deployment.rpcUrl).href === new URL(primary.rpcUrl).href &&
      JSON.stringify(deployment.nativeCurrency) === JSON.stringify(primary.nativeCurrency),
      "successor must retain the chain, RPC, environment and native units.");
    require_(!same(deployment.factory, primary.factory), "successor Factory must be distinct from V1.");
    require_(deployment.security && deployment.payments, "complete security and payment bundles are required.");
    for (const role of [...bundleRoles, "weth", "permit2"] as const)
      require_(deployment[role], "complete bundle is missing " + role + ".");
    for (const role of ["poolManager", "positionManager", "weth", "permit2"] as const)
      require_(primary[role] && same(deployment[role]!, primary[role]!), "upstream " + role + " cannot change.");
    require_(primary.payments, "primary payment provenance is required.");
    for (const role of ["weth", "v3Factory", "quoterV3", "quoterV4"] as const)
      require_(same(deployment.payments![role], primary.payments[role]), "payment upstream " + role + " cannot change.");
    for (const quote of deployment.quoteAssets) {
      const retained = primary.quoteAssets.find(item => same(item.address, quote.address));
      require_(retained && retained.decimals === quote.decimals, "successor quote units must match reviewed V1 assets.");
    }
    require_(deployment.quoteAssets.length === primary.quoteAssets.length, "successor must retain all reviewed quote assets.");
    const source = record(entry.source, "source");
    exact(source, ["schema", "version", "reviewId", "chainId", "factory", "hookSalt", "artifacts"], "source");
    require_(source.schema === DUO_GENERATION_SOURCE_SCHEMA && source.version === 2, "unknown reviewed source schema or version.");
    require_(typeof source.reviewId === "string" && source.reviewId.trim().length > 0 && source.reviewId.length <= 256,
      "reviewId is required.");
    require_(source.chainId === deployment.chainId && same(addr(source.factory, "source Factory"), deployment.factory),
      "source chain or Factory differs from its complete bundle.");
    const artifacts = record(source.artifacts, "artifacts");
    exact(artifacts, Object.keys(DUO_V2_COMPONENT_ARTIFACTS), "20-node artifacts");
    const normalized = Object.fromEntries(Object.entries(DUO_V2_COMPONENT_ARTIFACTS).map(([role, expected]) => {
      const item = record(artifacts[role], role);
      exact(item, ["artifact", "address", "runtimeCodeHash"], role);
      require_(item.artifact === expected, role + " has an unreviewed source recipe.");
      return [role, Object.freeze({ artifact: expected, address: addr(item.address, role), runtimeCodeHash: hash(item.runtimeCodeHash) })];
    })) as Record<DuoV2Component, Artifact>;
    require_(new Set(Object.values(normalized).map(item => item.address.toLowerCase())).size === 20,
      "all 20 component addresses must be distinct.");
    for (const role of bundleRoles)
      require_(same(normalized[role].address, deployment[role]!), role + " differs from its Deployment bundle.");
    return Object.freeze({ policyVersion: 2 as const, deployment,
      source: Object.freeze({ schema: DUO_GENERATION_SOURCE_SCHEMA, version: 2 as const,
        reviewId: source.reviewId, chainId: deployment.chainId, factory: deployment.factory, hookSalt: hash(source.hookSalt),
        artifacts: Object.freeze(normalized) }) });
  });
  return Object.freeze({ schema: DUO_GENERATION_REGISTRY_SCHEMA, version: 1, primaryFactory, generations: Object.freeze(generations) });
}

